compliant:
import { Effect, Schema } from "effect"

class MissingArtifact extends Schema.TaggedError<MissingArtifact>()("MissingArtifact", {
  artifactId: Schema.String,
  registry: Schema.String
}) {}

const ReadyArtifact = Schema.TaggedStruct("ReadyArtifact", {
  artifactId: Schema.String,
  downloadUrl: Schema.String,
  size: Schema.Number
})

interface ArtifactRecord {
  readonly downloadUrl: string
  readonly size: number
}

export const resolveArtifact = (
  registry: string,
  records: ReadonlyMap<string, ArtifactRecord>,
  artifactId: string
) =>
  Effect.gen(function*() {
    const record = records.get(artifactId)
    if (record === undefined) {
      return yield* new MissingArtifact({ artifactId, registry })
    }

    return ReadyArtifact.make({
      artifactId,
      downloadUrl: record.downloadUrl,
      size: record.size
    })
  })
